      "riteData": {
        "ZH": {
          "vigil_prayer_1": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：全能永生的天主，祢在創造萬物的工程上顯示出祢奇妙的智慧；求祢"
              },
              {
                "sp": "",
                "text": "幫助我們被救贖的人都能了解祢藉着我們的逾越羔羊基督的犧牲、所完成的救世工程，"
              },
              {
                "sp": "",
                "text": "比第一次創造的世界更為奧妙。祂是天主，永生永王。"
              },
              {
                "sp": "",
                "text": "或：論人的創造"
              },
              {
                "sp": "",
                "text": "天主，祢奇妙地創造了人類，更加奇妙地救贖了人類。求祢使我們善用祢恩賜的理"
              },
              {
                "sp": "",
                "text": "智，以抗拒罪惡的誘惑，因而得享永遠的福樂。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_prayer_2": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：天主、所有信者的慈父，祢曾許諾給亞巴郎，使他成為萬民之祖；並"
              },
              {
                "sp": "",
                "text": "藉基督的死亡與復活，實踐了祢的諾言：從世界各地召選新的子民。求祢使我們答覆祢"
              },
              {
                "sp": "",
                "text": "的召喚，欣然接受祢的邀請，度聖寵的新生活。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_prayer_3": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：天主，祢昔日所行的奇蹟，今日仍閃爍着光輝：正如祢昔日曾以大能"
              },
              {
                "sp": "",
                "text": "拯救了一個被迫害的民族，現在祢願以再生的洗禮拯救整個人類；求祢使天下萬民，都"
              },
              {
                "sp": "",
                "text": "能成為亞巴郎的子孫和祢特選的子民。以上所求，是因我們的主基督。"
              },
              {
                "sp": "",
                "text": "或："
              },
              {
                "sp": "",
                "text": "天主，祢藉福音的光照，顯示了祢在舊約時代所行奇蹟的意義：祢使紅海成為洗禮"
              },
              {
                "sp": "",
                "text": "的象徵，使被拯救的選民成為教會的標記。求祢使天下萬民都能分享以色列的信德和特"
              },
              {
                "sp": "",
                "text": "恩，並藉聖神而獲得再生。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_prayer_4": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：全能永生的天主，為了祢的光榮，求祢實踐祢昔日的諾言，使祢的選"
              },
              {
                "sp": "",
                "text": "民日益增多，並使古聖先賢堅信必將實現的諾言，在教會中應驗。以上所求，是因我們"
              },
              {
                "sp": "",
                "text": "的主基督。"
              }
            ]
          },
          "vigil_prayer_5": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：全能永生的天主，祢是世界唯一的希望；祢通過先知們的宣講，已經"
              },
              {
                "sp": "",
                "text": "把今夜所慶祝的奧蹟，啟示給我們；求祢幫助我們，成為祢忠誠的子民，因為祇有依賴"
              },
              {
                "sp": "",
                "text": "祢的啟發，我們才能修德行善。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_prayer_6": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：天主，祢常召請萬民加入祢的教會，以獲得救恩。求祢使所有領過洗"
              },
              {
                "sp": "",
                "text": "的人，都能不斷地獲得祢慈祥的照顧。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_prayer_7": {
            "lines": [
              {
                "sp": "",
                "text": "請大家祈禱：天主，祢有無限的權能，祢是永恆的真光。求祢仁慈地垂視祢的整個"
              },
              {
                "sp": "",
                "text": "教會，將祢的救恩有效地廣施給全人類，使普世萬民都能看到：跌倒的必將站起，古老"
              },
              {
                "sp": "",
                "text": "的將要革新，破碎的必要藉着基督重歸完整。祂是萬物的根源，永生永王。"
              },
              {
                "sp": "",
                "text": "或："
              },
              {
                "sp": "",
                "text": "請大家祈禱：天主，祢以舊約和新約的訓言，教導我們如何慶祝這逾越節的奧蹟。"
              },
              {
                "sp": "",
                "text": "求祢幫助我們了解祢對我們的慈愛，使我們現世接受祢的恩惠，也加強我們對將來永福"
              },
              {
                "sp": "",
                "text": "的希望。以上所求，是因我們的主基督。"
              },
              {
                "sp": "",
                "text": "或：（本夜如有人領洗）："
              },
              {
                "sp": "",
                "text": "請大家祈禱：全能永生的天主，求祢親臨這顯示偉大仁愛的聖事，並派遣施慰的聖"
              },
              {
                "sp": "",
                "text": "神，使今夜即將領受洗禮的信友，成為祢新選的子民，也使我們卑微的服務，藉着祢的"
              },
              {
                "sp": "",
                "text": "助祐，獲得圓滿的效果。以上所求，是因我們的主基督。"
              }
            ]
          },
          "vigil_blessing": {
            "lines": [
              {
                "sp": "",
                "text": "－ 願全能的天主，藉著今天逾越節的隆重典禮，降福你們，護祐你們脫離一切罪惡。"
              },
              {
                "sp": "",
                "text": "答：阿們。"
              },
              {
                "sp": "",
                "text": "－ 願天主因獨生子的復活，恩賜你們常生，永享真福。答：阿們。"
              },
              {
                "sp": "",
                "text": "－ 你們歡欣慶祝了耶穌復活良辰，但願你們懷著愉快的心情，去參加祂天上永福的慶"
              },
              {
                "sp": "",
                "text": "節。答：阿們。"
              },
              {
                "sp": "",
                "text": "－ 願全能的天主，聖父、聖子、聖神，降福你們，並常與你們同在。答：阿們。"
              }
            ]
          },
          "vigil_dismissal": {
            "lines": [
              {
                "sp": "",
                "text": "執事或主祭：彌撒禮成，阿肋路亞，阿肋路亞。"
              },
              {
                "sp": "",
                "text": "信友：感謝天主，阿肋路亞，阿肋路亞。"
              }
            ]
          }
        }
      },
